{"script":"() => {
  const sections = document.querySelectorAll('section');
  const result = [];
  sections.forEach(section => {
    const headingBtn = section.querySelector('button');
    if (headingBtn) {
      const venueText = headingBtn.innerText.trim();
      const table = section.querySelector('table');
      const rows = table ? table.querySelectorAll('tbody tr') : [];
      const races = [];
      let maxRunners = 0;
      let maxRaceName = '';
      let maxTime = '';
      rows.forEach(row => {
        const cells = row.querySelectorAll('td');
        if (cells.length >= 4) {
          const time = cells[0].innerText.trim();
          const runners = parseInt(cells[1].innerText.trim()) || 0;
          const raceName = cells[2].innerText.trim();
          races.push({time, runners, raceName});
          if (runners > maxRunners) {
            maxRunners = runners;
            maxRaceName = raceName;
            maxTime = time;
          }
        }
      });
      result.push({venue: venueText, races, maxRunners, maxRaceName, maxTime});
    }
  });
  return result;
}"}

